SELECT toJSONString(groupArray(tuple(hostname,samples,first,last,min_bytes,max_bytes))) AS payload FROM (SELECT hostname,count() AS samples,min(event_time) AS first,max(event_time) AS last,min(value) AS min_bytes,max(value) AS max_bytes FROM clusterAllReplicas(default,merge('system','^asynchronous_metric_log')) WHERE metric='CGroupMemoryTotal' AND event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') GROUP BY hostname ORDER BY hostname LIMIT 10) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000,skip_unavailable_shards=0;
